using UnityEngine;

namespace AISystem
{
    /// <summary>
    /// The companion comments on events in her own words (generated by the LLM, not written lines):
    /// a fight starts, an enemy falls, the player gets badly hurt, or a scene trigger calls React.
    /// </summary>
    [RequireComponent(typeof(NPCAgent))]
    public class CompanionReactions : MonoBehaviour
    {
        [Tooltip("Minimum seconds between two comments.")]
        [SerializeField] private float cooldown = 12f;
        [Tooltip("Player health fraction below which she reacts to the player's wounds.")]
        [SerializeField, Range(0f, 1f)] private float hurtThreshold = 0.4f;

        private NPCAgent _agent;
        private CompanionController _companion;
        private Health _playerHealth;
        private float _nextComment;
        private bool _hurtCommented;

        void Awake()
        {
            _agent = GetComponent<NPCAgent>();
            _companion = GetComponent<CompanionController>();
        }

        void Start()
        {
            if (_companion != null) _companion.OnFightStarted += HandleFightStarted;

            _playerHealth = GameObject.FindWithTag("Player").GetComponent<Health>();
            if (_playerHealth != null) _playerHealth.OnHealthChanged += HandlePlayerHealth;

            foreach (var health in FindObjectsByType<Health>(FindObjectsSortMode.None))
                if (health.Team.Team == Team.Enemy)
                    health.OnDied += HandleEnemyDied;
        }

        void OnDestroy()
        {
            if (_companion != null) _companion.OnFightStarted -= HandleFightStarted;
            if (_playerHealth != null) _playerHealth.OnHealthChanged -= HandlePlayerHealth;
        }

        /// <summary>Asks the companion to react to a situation. Hook it to scene triggers.</summary>
        public void React(string situation)
        {
            if (Time.time < _nextComment) return;
            if (AISystemManager.Instance.RequestNPCComment(_agent, situation))
                _nextComment = Time.time + cooldown;
        }

        private void HandleFightStarted() => React("Skeletons attack and you draw your sword to fight beside the player.");

        private void HandleEnemyDied() => React("A skeleton you were fighting just fell apart.");

        private void HandlePlayerHealth()
        {
            if (_playerHealth.IsDead) return;
            if (_playerHealth.Fraction >= hurtThreshold) { _hurtCommented = false; return; }
            if (_hurtCommented) return;
            _hurtCommented = true;
            React("The player is badly wounded and bleeding.");
        }
    }
}
